/* MODULE tu01 · Bước 8 Tối ưu · Tối ưu chuyển đổi trang đích
   10 bài × 7 câu. Trang đích của website riêng (không phải trang sàn). Mọi con số là MINH HOẠ và tự khớp nhau. */
BAI_ADD({ mod:'tu01', lessons:[

/* ------------------------------------------------------------------ 01 */
{ id:'B:tu01-01', skill:'creative', read:'6 phút', t:'Khách thấy gì trong 5 giây đầu khi mở trang?',
  situation:'Một thương hiệu nến thơm ở Đà Lạt chạy quảng cáo về website. Mở trang trên điện thoại, màn hình đầu tiên là ảnh bìa rừng thông thật to, logo và dòng chữ "Chào mừng bạn đến với thế giới của chúng tôi". Sản phẩm, giá và nút mua nằm phía dưới, phải cuộn hai lần mới thấy. Công cụ đo cho biết 60% người vào không cuộn chút nào.',
  concept:{ name:'Phần nhìn thấy đầu tiên (above the fold)',
    body:'Là phần trang hiện ra trước khi khách cuộn. Với nhiều người, đó là <b>toàn bộ</b> trang, vì họ quyết định ở lại hay thoát chỉ trong vài giây. Phần này phải trả lời ba câu: đây là gì, có gì cho tôi, bước tiếp theo là gì. Công thức gọn: một dòng tiêu đề nói lợi ích, một ảnh sản phẩm thật, một nút hành động. Lời chào, ảnh không khí và câu chuyện thương hiệu để xuống dưới cho người đã quan tâm.' },
  example:'Trang nến đổi màn hình đầu: tiêu đề "Nến sáp đậu nành, cháy 40 giờ, không khói đen", ảnh ba mùi bán chạy kèm giá 189.000đ, nút "Chọn mùi". Nếu 60% người không cuộn, trước đây họ rời đi mà chưa thấy sản phẩm; nay cả 60% đó đều thấy giá và nút. Trên 5.000 lượt vào mỗi tuần, đó là 3.000 người lần đầu được mời mua.',
  takeaway:'Màn hình đầu tiên phải nói đây là gì, lợi gì cho khách và bấm vào đâu.',
  apply:'Mở trang đích của một thương hiệu bạn thích trên điện thoại, đừng cuộn. Nói trong 60 giây: trang có trả lời đủ ba câu không, thiếu câu nào.',
  mistakes:['Dành màn hình đầu cho lời chào và ảnh không khí vì "cho sang".','Tin rằng khách sẽ tự cuộn xuống tìm giá nếu họ thật sự quan tâm.'],
  q:[
  { type:'mcq', stem:'Đoán trước: 60% người vào trang nến không cuộn. Nhận định nào hợp lý nhất?',
    options:[{k:'a',t:'Với 60% đó, màn hình đầu là cả trang — họ chưa hề thấy giá'},{k:'b',t:'60% đó là khách không có nhu cầu, trang có tốt mấy cũng không giữ được họ'},
             {k:'c',t:'Trang tải quá nhanh nên khách chưa kịp đọc đã bấm quay lại'},{k:'d',t:'Họ đã xem đủ ảnh bìa và sẽ tự quay lại mua vào hôm khác'}],
    answer:'a', why:{a:'Đúng. Không cuộn nghĩa là mọi thứ bên dưới không tồn tại với họ, kể cả sản phẩm và nút mua.',
      b:'Họ bấm vào từ quảng cáo nên có quan tâm ban đầu; chưa thấy sản phẩm thì chưa thể kết luận họ không có nhu cầu.',
      c:'Tải nhanh không làm người ta rời trang; tải chậm mới làm.',
      d:'Ảnh bìa không cho họ lý do quay lại; phần lớn người đã rời trang thì không trở lại.'} },
  { type:'mcq', stem:'Bạn chỉ được sửa màn hình đầu của trang nến. Bạn chọn đặt gì lên đó?',
    options:[{k:'a',t:'Câu chuyện người sáng lập bỏ phố lên núi làm nến, để tạo cảm xúc trước khi bán'},{k:'b',t:'Tiêu đề nói lợi ích, ảnh sản phẩm có giá và một nút chọn mùi'},
             {k:'c',t:'Giữ ảnh rừng thông, thêm mũi tên nhấp nháy mời khách cuộn xuống'},{k:'d',t:'Danh sách đủ 24 mùi nến dạng lưới nhỏ để khách thấy nhiều lựa chọn'}],
    answer:'b', why:{a:'Câu chuyện hay cho người đã quan tâm; đặt lên đầu thì người vội vẫn chưa biết đây bán gì.',
      b:'Đúng. Trả lời ngay ba câu: là gì, lợi gì, bấm đâu.',
      c:'Mũi tên chỉ xin khách làm thêm một việc; trang vẫn chưa cho họ lý do để làm.',
      d:'24 ô nhỏ trên điện thoại khó đọc và làm khách phân vân; màn hình đầu cần một lựa chọn rõ.'} },
  { type:'calc', stem:'Trang có 5.000 lượt vào mỗi tuần, 60% không cuộn. Sau khi đưa sản phẩm và nút lên màn hình đầu, có thêm bao nhiêu người mỗi tuần được thấy nút mua (giả sử trước đây người không cuộn không thấy)?',
    unit:'người', ans:3000, tol:1, wrong:[[2000,'NHAM_TI_LE_ROI'],[60,'NHAM_SO_TUYET_DOI']], errors:['NHAM_TI_LE_ROI'],
    steps:['Người không cuộn = 5.000 × 60% = 3.000.','Trước đây họ không thấy nút, nay thấy → thêm <b>3.000 người</b>.'] },
  { type:'mcq', stem:'Tiêu đề nào phù hợp nhất cho màn hình đầu trang bán bình giữ nhiệt?',
    options:[{k:'a',t:'Chào mừng bạn đến với ThermoViet'},{k:'b',t:'Chất lượng tạo nên sự khác biệt đẳng cấp'},
             {k:'c',t:'Giữ đá 24 giờ trong xe nắng — bảo hành 2 năm'},{k:'d',t:'Bộ sưu tập mùa thu mới nhất đã chính thức ra mắt'}],
    answer:'c', why:{a:'Lời chào không nói bán gì hay lợi gì.',
      b:'Câu chung chung, thương hiệu nào cũng nói được.',
      c:'Đúng. Lợi ích cụ thể, gắn với tình huống thật của khách, kèm một lời cam kết.',
      d:'Nói về hãng chứ chưa nói khách được gì; "mới" không phải lợi ích.'} },
  { type:'mcq', stem:'Trang đích có ảnh bìa là video tự chạy dung lượng lớn ở màn hình đầu. Rủi ro chính là gì?',
    options:[{k:'a',t:'Video làm trang trông kém chuyên nghiệp hơn so với ảnh tĩnh'},{k:'b',t:'Video chiếm chỗ của tiêu đề và nút, lại làm trang tải chậm trên 4G'},
             {k:'c',t:'Khách xem video quá lâu nên quên mất việc bấm vào nút mua bên dưới'},{k:'d',t:'Video tự chạy luôn tăng chuyển đổi nên không có rủi ro gì'}],
    answer:'b', why:{a:'Video có thể rất chuyên nghiệp; vấn đề là chỗ và tốc độ.',
      b:'Đúng. Hai cái giá: màn hình đầu mất thông điệp, và nhiều người thoát trước khi video tải xong.',
      c:'Ít người xem hết video tự chạy; nguy cơ lớn hơn là họ rời đi khi nó còn đang tải.',
      d:'Không có yếu tố nào "luôn" tăng chuyển đổi; video nặng thường làm ngược lại trên mạng di động.'} },
  { type:'mcq', stem:'Một trang dịch vụ vệ sinh máy lạnh có màn hình đầu: tiêu đề "Vệ sinh máy lạnh tại nhà trong 45 phút", giá từ 150.000đ, nút "Đặt lịch". Còn thiếu gì đáng kể nhất?',
    options:[{k:'a',t:'Thiếu khu vực phục vụ — khách ở quận xa chưa biết có được phục vụ không'},{k:'b',t:'Thiếu lời chào thân thiện ở đầu trang để tạo thiện cảm với khách mới vào'},
             {k:'c',t:'Thiếu phần lịch sử công ty và giấy chứng nhận thành lập'},{k:'d',t:'Không thiếu gì, nên thêm càng nhiều nút càng tốt'}],
    answer:'a', why:{a:'Đúng. Với dịch vụ tại nhà, "có tới chỗ tôi không" là câu hỏi đầu tiên; thiếu nó khách phải cuộn đi tìm.',
      b:'Lời chào không giúp khách quyết định.',
      c:'Lịch sử công ty để phía dưới cho người cần thêm niềm tin.',
      d:'Nhiều nút làm loãng hành động chính.'} },
  { type:'mcq', stem:'Sếp muốn giữ ảnh rừng thông vì "đó là nhận diện thương hiệu". Cách dung hoà nào hợp lý nhất?',
    options:[{k:'a',t:'Bỏ hẳn ảnh rừng thông khỏi toàn bộ website để tập trung bán'},{k:'b',t:'Giữ nguyên ảnh bìa như cũ và chuyển nút mua lên thanh menu trên cùng'},
             {k:'c',t:'Làm ảnh rừng thông mờ đi và chèn thêm năm dòng chữ giới thiệu lên trên'},{k:'d',t:'Dùng ảnh nến đặt trên nền rừng thông, kèm tiêu đề lợi ích và nút'}],
    answer:'d', why:{a:'Không cần bỏ nhận diện; chỉ cần nhận diện phục vụ việc bán.',
      b:'Nút trên menu nhỏ và dễ bị bỏ qua; màn hình đầu vẫn không nói bán gì.',
      c:'Năm dòng chữ trên ảnh mờ khó đọc trên điện thoại và vẫn không có sản phẩm.',
      d:'Đúng. Sản phẩm là nhân vật chính, rừng thông là bối cảnh — vừa giữ chất thương hiệu vừa rõ việc bán.'} }
  ] },

/* ------------------------------------------------------------------ 02 */
{ id:'B:tu01-02', skill:'creative', read:'6 phút', t:'Trang đích nên có một mục tiêu hay năm lựa chọn?',
  situation:'Một trung tâm tiếng Anh chạy quảng cáo "Học thử IELTS miễn phí". Trang đích có: nút đăng ký học thử, nút tải tài liệu, nút xem lịch khai giảng, nút theo dõi fanpage, menu đầy đủ tám mục và một ô chat. Tỉ lệ đăng ký học thử chỉ 2%.',
  concept:{ name:'Một trang, một mục tiêu',
    body:'Trang đích khác trang chủ: nó sinh ra cho <b>một</b> hành động, khớp với lời hứa đã đưa khách tới. Mỗi đường thoát khác — menu, liên kết mạng xã hội, nút phụ — đều chia sự chú ý. Khách không làm được gì thì sẽ chọn làm cái dễ nhất, thường là bấm đi chỗ khác. Quy tắc: bỏ menu, giữ một nút chính lặp lại vài lần dọc trang; các lựa chọn phụ nếu cần thì để nhỏ ở cuối trang.' },
  example:'Trung tâm bỏ menu, bỏ nút fanpage, chuyển "tải tài liệu" thành quà tặng sau khi đăng ký. Trang còn một nút "Giữ chỗ học thử" xuất hiện ba lần. Với 4.000 lượt vào mỗi tháng, tỉ lệ đăng ký từ 2% lên 3,5% nghĩa là từ 80 lên 140 người học thử — thêm 60 người mà không tốn thêm đồng quảng cáo nào.',
  takeaway:'Mỗi nút phụ là một cửa thoát; trang đích chỉ nên có một cửa vào.',
  apply:'Đếm số chỗ bấm được trên một trang đích bạn biết. Nói trong 60 giây: chỗ nào phục vụ mục tiêu chính, chỗ nào nên bỏ.',
  mistakes:['Thêm nhiều lựa chọn vì sợ khách "không tìm thấy thứ họ cần".','Dùng trang chủ làm trang đích cho quảng cáo.'],
  q:[
  { type:'mcq', stem:'Đoán trước: bỏ bớt nút phụ và menu thường làm tỉ lệ đăng ký thay đổi thế nào?',
    options:[{k:'a',t:'Giảm, vì khách thấy trang nghèo nàn và kém uy tín'},{k:'b',t:'Thường tăng, vì sự chú ý dồn vào một hành động'},
             {k:'c',t:'Giữ nguyên, vì người muốn đăng ký thì đằng nào cũng sẽ đăng ký'},{k:'d',t:'Tăng, nhưng chỉ khi đồng thời giảm giá khoá học chính'}],
    answer:'b', why:{a:'Trang đích gọn không bị xem là kém uy tín nếu nội dung rõ và có bằng chứng.',
      b:'Đúng. Ít lối rẽ thì nhiều người đi hết đường tới nút chính.',
      c:'Người đang phân vân rất dễ bị kéo sang nút phụ và không quay lại.',
      d:'Giảm giá không cần thiết; bỏ nhiễu tự nó đã có tác dụng.'} },
  { type:'mcq', stem:'Quản lý muốn giữ nút "Theo dõi fanpage" trên trang đích học thử để tăng người theo dõi. Bạn đề xuất gì?',
    options:[{k:'a',t:'Giữ nút fanpage ngay cạnh nút đăng ký cho cân bằng hai mục tiêu'},{k:'b',t:'Đặt nút fanpage lên trên cùng vì người theo dõi có giá trị lâu dài hơn'},
             {k:'c',t:'Bỏ khỏi trang đích; mời theo dõi fanpage ở trang cảm ơn sau khi đăng ký'},{k:'d',t:'Làm hai trang đích giống hệt nhau, mỗi trang một nút, chạy chung một quảng cáo'}],
    answer:'c', why:{a:'Hai nút ngang nhau chia đôi sự chú ý đúng lúc khách đang quyết định.',
      b:'Quảng cáo hứa học thử; đẩy fanpage lên đầu là trái lời hứa.',
      c:'Đúng. Trang cảm ơn là chỗ tốt cho mục tiêu phụ: khách đã làm xong việc chính.',
      d:'Hai trang chung một quảng cáo không giải quyết được gì mà còn khó đo.'} },
  { type:'calc', stem:'Trang có 4.000 lượt vào mỗi tháng. Tỉ lệ đăng ký tăng từ 2% lên 3,5%. Mỗi tháng có thêm bao nhiêu người đăng ký học thử?',
    unit:'người', ans:60, tol:0.5, wrong:[[1.5,'NHAM_DIEM_PHAN_TRAM'],[140,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Trước: 4.000 × 2% = 80 người.','Sau: 4.000 × 3,5% = 140 người.','Thêm: 140 − 80 = <b>60 người</b>.'] },
  { type:'mcq', stem:'Vì sao dùng trang chủ làm trang đích cho quảng cáo "Học thử IELTS" thường kém?',
    options:[{k:'a',t:'Trang chủ phục vụ mọi khách nên không khớp riêng lời hứa học thử'},{k:'b',t:'Trang chủ luôn tải chậm hơn mọi trang con khác của website'},
             {k:'c',t:'Nền tảng quảng cáo không cho phép gắn đường dẫn trang chủ'},{k:'d',t:'Trang chủ không đo được tỉ lệ chuyển đổi bằng công cụ phân tích web'}],
    answer:'a', why:{a:'Đúng. Khách tới vì một lời hứa cụ thể mà trang chủ lại bày cả cửa hàng.',
      b:'Tốc độ tuỳ cách làm trang, không phụ thuộc đó là trang chủ.',
      c:'Nền tảng quảng cáo cho phép gắn trang chủ; vấn đề là hiệu quả.',
      d:'Trang nào cũng đo được; vấn đề là thiết kế cho mục tiêu.'} },
  { type:'mcq', stem:'Ô chat bật tự động che nửa màn hình điện thoại ngay khi khách vào trang. Nên xử lý thế nào?',
    options:[{k:'a',t:'Giữ nguyên, vì chat là kênh chốt đơn hiệu quả nhất của mọi trung tâm'},{k:'b',t:'Bỏ hẳn chat để trang tuyệt đối chỉ còn một mục tiêu duy nhất'},
             {k:'c',t:'Cho chat bật lại liên tục mỗi 10 giây để chắc khách không bỏ lỡ'},{k:'d',t:'Thu thành biểu tượng nhỏ ở góc, không tự mở che nội dung'}],
    answer:'d', why:{a:'Chat có ích, nhưng che nửa màn hình thì khách không đọc được lời hứa.',
      b:'Chat là đường phụ hỗ trợ người còn thắc mắc; không cần bỏ, chỉ cần không chen ngang.',
      c:'Bật lại liên tục là làm phiền, khách sẽ thoát.',
      d:'Đúng. Vẫn có cho người cần hỏi, nhưng không cướp chỗ của hành động chính.'} },
  { type:'mcq', stem:'Một cửa hàng giày chạy quảng cáo cho một mẫu giày chạy bộ. Trang đích nào phù hợp nhất?',
    options:[{k:'a',t:'Trang danh mục toàn bộ 120 mẫu giày để khách so sánh thoải mái'},{k:'b',t:'Trang giới thiệu cửa hàng và hệ thống các chi nhánh trên toàn quốc'},
             {k:'c',t:'Trang riêng của đúng mẫu đó, có chọn size và nút mua'},{k:'d',t:'Trang chủ có banner mẫu giày đó nằm ở vị trí thứ ba trong slide'}],
    answer:'c', why:{a:'Khách bấm vì một mẫu; bắt họ tìm lại trong 120 mẫu là mất khách.',
      b:'Không liên quan tới lời hứa của quảng cáo.',
      c:'Đúng. Khớp lời hứa, một hành động: chọn size và mua.',
      d:'Banner trượt thứ ba thì phần lớn khách không bao giờ thấy.'} },
  { type:'mcq', stem:'Trang đích dài có một nút "Đăng ký" ở cuối. Cách đặt nút nào tốt hơn?',
    options:[{k:'a',t:'Lặp lại cùng một nút ở màn hình đầu, giữa trang và cuối trang'},{k:'b',t:'Chỉ để một nút ở cuối, vì khách đọc hết mới là khách chất lượng'},
             {k:'c',t:'Đặt mỗi đoạn một nút khác nhau: đăng ký, tải tài liệu, xem lịch, gọi'},{k:'d',t:'Chỉ đặt nút trên thanh menu vì khách quen tìm ở đó'}],
    answer:'a', why:{a:'Đúng. Khách sẵn sàng ở những thời điểm khác nhau; cùng một hành động nên có mặt ở mỗi điểm đó.',
      b:'Nhiều người đã sẵn sàng từ sớm; bắt họ cuộn hết là để lọt.',
      c:'Mỗi đoạn một nút khác là quay về tình trạng nhiều mục tiêu.',
      d:'Trang đích nên bỏ menu; nút trên menu cũng nhỏ và dễ bị bỏ qua.'} }
  ] },

/* ------------------------------------------------------------------ 03 */
{ id:'B:tu01-03', skill:'measure', read:'7 phút', t:'Form đăng ký có 9 trường — bỏ bớt cái nào?',
  situation:'Một công ty nội thất chạy quảng cáo "Nhận báo giá thiết kế miễn phí". Form hỏi: họ tên, số điện thoại, email, ngày sinh, địa chỉ đầy đủ, diện tích căn hộ, ngân sách, phong cách yêu thích, biết đến qua đâu. 1.000 người mở form, chỉ 80 người gửi.',
  concept:{ name:'Mỗi trường là một cái giá',
    body:'Mỗi ô phải điền là thêm một lần khách cân nhắc "có đáng không". Với mỗi trường, hỏi: <b>không có thông tin này thì bước tiếp theo có làm được không?</b> Nếu vẫn làm được, bỏ hoặc hỏi sau (trong cuộc gọi, ở bước hai). Các trường nhạy cảm như ngày sinh, thu nhập, địa chỉ chi tiết làm người ta ngần ngại nhất. Form ngắn có thể kéo thêm vài người ít nghiêm túc, nên đo cả tỉ lệ gửi form lẫn tỉ lệ khách chốt được.' },
  example:'Để báo giá, nhân viên chỉ cần gọi được khách và biết sơ quy mô. Form rút còn ba trường: tên, số điện thoại, diện tích (chọn khoảng). Tỉ lệ gửi từ 8% lên 20%: 1.000 người mở form nay có 200 người gửi. Tỉ lệ chốt hợp đồng từ người gửi giảm từ 10% xuống 7% vì có thêm người chỉ tò mò, nhưng số hợp đồng vẫn tăng từ 8 lên 14.',
  takeaway:'Chỉ hỏi điều cần cho bước kế tiếp; phần còn lại hỏi khi khách đã tin bạn.',
  apply:'Chọn một form bạn từng điền. Với từng trường, nói trong 60 giây: bỏ, giữ hay chuyển sang bước sau, và vì sao.',
  mistakes:['Hỏi hết mọi thứ ngay từ đầu vì "sau này sales đỡ phải hỏi".','Chỉ nhìn tỉ lệ gửi form tăng mà không kiểm tra số khách chốt được.'],
  q:[
  { type:'mcq', stem:'Đoán trước: form 9 trường có tỉ lệ gửi 8%. Rút còn 3 trường cần thiết, điều gì dễ xảy ra nhất?',
    options:[{k:'a',t:'Tỉ lệ gửi giảm, vì khách thấy form ngắn thì nghĩ công ty làm ăn không chuyên nghiệp'},{k:'b',t:'Tỉ lệ gửi gần như giữ nguyên vì số trường không phải lý do bỏ form'},
             {k:'c',t:'Tỉ lệ gửi tăng rõ, dù chất lượng từng người có thể giảm nhẹ'},{k:'d',t:'Tỉ lệ gửi tăng gấp chín lần vì số trường giảm'}],
    answer:'c', why:{a:'Khách hiếm khi đánh giá uy tín qua độ dài form; họ cảm thấy nhẹ nhõm hơn.',
      b:'Số trường, nhất là trường nhạy cảm, là một lý do bỏ form rất phổ biến.',
      c:'Đúng. Ít rào cản hơn thì nhiều người gửi hơn; cần theo dõi cả chất lượng.',
      d:'Không có quan hệ tỉ lệ thuận đơn giản như vậy.'} },
  { type:'mcq', stem:'Trong 9 trường của form nội thất, bạn chọn giữ ba trường nào?',
    options:[{k:'a',t:'Họ tên, email, ngày sinh — đủ để chăm sóc khách lâu dài'},{k:'b',t:'Tên, số điện thoại, diện tích căn hộ theo khoảng'},
             {k:'c',t:'Ngân sách, phong cách, biết đến qua đâu — để phân loại khách trước khi gọi'},{k:'d',t:'Địa chỉ đầy đủ, ngân sách và số điện thoại để lọc khách nghiêm túc'}],
    answer:'b', why:{a:'Không có số điện thoại thì không gọi báo giá được; ngày sinh chưa cần.',
      b:'Đúng. Đủ để liên hệ và ước quy mô; mọi thứ khác hỏi trong cuộc gọi.',
      c:'Thiếu cách liên hệ; phân loại để sau khi nói chuyện.',
      d:'Địa chỉ và ngân sách là hai câu khiến khách ngần ngại nhất ở bước đầu.'} },
  { type:'calc', stem:'Trước: 1.000 người mở form, gửi 8%, chốt 10% người gửi. Sau: gửi 20%, chốt 7% người gửi. Số hợp đồng tăng thêm bao nhiêu?',
    unit:'hợp đồng', ans:6, tol:0.1, wrong:[[12,'QUEN_TI_LE_CHUYEN_DOI'],[120,'QUEN_TI_LE_CHUYEN_DOI']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Trước: 1.000 × 8% × 10% = 8 hợp đồng.','Sau: 1.000 × 20% × 7% = 14 hợp đồng.','Tăng: 14 − 8 = <b>6 hợp đồng</b>.'] },
  { type:'mcq', stem:'Sau khi rút form, số người gửi tăng gấp 2,5 lần nhưng đội sales than "toàn khách tò mò". Nên nhìn chỉ số nào để phán xử?',
    options:[{k:'a',t:'Tỉ lệ gửi form, vì nó là mục tiêu chính của trang đích'},{k:'b',t:'Tỉ lệ chốt trên người gửi, vì nó giảm nghĩa là form ngắn thất bại'},
             {k:'c',t:'Số cuộc gọi sales phải thực hiện, vì nó cho biết khối lượng công việc'},{k:'d',t:'Số hợp đồng trên cùng một lượng khách vào trang'}],
    answer:'d', why:{a:'Tỉ lệ gửi tăng chưa chắc ra thêm doanh thu.',
      b:'Tỉ lệ chốt giảm là bình thường khi thêm người ít nghiêm túc; cái cần xem là tổng số chốt.',
      c:'Khối lượng việc là chi phí, cần xét, nhưng không nói trang có hiệu quả hơn không.',
      d:'Đúng. Đo tới cuối phễu mới biết form ngắn có thật sự tốt hơn.'} },
  { type:'mcq', stem:'Một spa muốn giữ trường "Ngày sinh" để gửi quà sinh nhật. Cách làm hợp lý nhất là gì?',
    options:[{k:'a',t:'Hỏi ngày sinh sau, ví dụ khi khách tới spa lần đầu hoặc trong tin nhắn cảm ơn'},{k:'b',t:'Để trường ngày sinh bắt buộc ở form đặt lịch để không ai quên điền'},
             {k:'c',t:'Bỏ hẳn quà sinh nhật vì nó làm form đặt lịch dài thêm một trường'},{k:'d',t:'Đưa ngày sinh lên làm trường đầu tiên để khách thấy spa quan tâm'}],
    answer:'a', why:{a:'Đúng. Mục tiêu vẫn đạt, chỉ đổi thời điểm hỏi sang lúc khách đã tin.',
      b:'Bắt buộc một trường không cần cho việc đặt lịch là tăng rào cản.',
      c:'Không cần bỏ chương trình; chỉ cần hỏi ở bước khác.',
      d:'Trường nhạy cảm đứng đầu làm nhiều người bỏ ngay.'} },
  { type:'mcq', stem:'Công ty chia form thành hai bước: bước 1 chỉ hỏi số điện thoại, bước 2 hỏi diện tích và phong cách (không bắt buộc). Ưu điểm chính là gì?',
    options:[{k:'a',t:'Khách mất nhiều thời gian hơn trên trang nên trang được xếp hạng cao hơn'},{k:'b',t:'Có được liên hệ ngay cả khi khách bỏ dở bước 2'},
             {k:'c',t:'Hai bước trông chuyên nghiệp hơn, làm khách tin công ty hơn'},{k:'d',t:'Bước 2 buộc khách phải điền đủ nên dữ liệu đầy đủ hơn trước'}],
    answer:'b', why:{a:'Thời gian trên trang không phải mục tiêu; kết quả mới là mục tiêu.',
      b:'Đúng. Thông tin quan trọng nhất được ghi nhận trước; phần thêm là tuỳ chọn.',
      c:'Uy tín không đến từ số bước.',
      d:'Bước 2 không bắt buộc; nếu bắt buộc thì lại quay về form dài.'} },
  { type:'mcq', stem:'Trường "Biết đến chúng tôi qua đâu" nên xử lý thế nào khi website đã gắn đo nguồn truy cập?',
    options:[{k:'a',t:'Giữ bắt buộc vì đó là cách duy nhất biết kênh nào hiệu quả'},{k:'b',t:'Chuyển thành ô tự do để khách viết dài và chi tiết hơn'},
             {k:'c',t:'Đưa lên đầu form để khách trả lời lúc còn nhiều kiên nhẫn'},{k:'d',t:'Bỏ khỏi form, dùng dữ liệu nguồn đo sẵn; nếu cần, hỏi trong cuộc gọi'}],
    answer:'d', why:{a:'Đã đo nguồn tự động thì trường này trùng lặp, lại hay bị điền đại.',
      b:'Ô tự do càng tốn công, càng ít người điền.',
      c:'Đặt câu không cần thiết lên đầu là tiêu kiên nhẫn sai chỗ.',
      d:'Đúng. Không bắt khách làm việc mà hệ thống đã làm được.'} }
  ] },

/* ------------------------------------------------------------------ 04 */
{ id:'B:tu01-04', skill:'measure', read:'7 phút', t:'Trang tải 6 giây thì mất bao nhiêu khách?',
  situation:'Một shop mỹ phẩm chạy quảng cáo về website. Trang sản phẩm có sáu ảnh chụp chưa nén, mỗi ảnh 4MB, cùng nhiều đoạn mã theo dõi. Trên 4G, trang mất khoảng 6 giây mới hiện nội dung. Báo cáo quảng cáo ghi 10.000 lượt bấm, nhưng công cụ phân tích web chỉ ghi 6.500 lượt xem trang.',
  concept:{ name:'Tốc độ tải và tỉ lệ rời',
    body:'Mỗi giây chờ là một nhóm khách bấm quay lại. Người đã rời trước khi trang tải xong thường <b>không được ghi</b> là lượt xem, nên khoảng chênh giữa lượt bấm quảng cáo và lượt xem trang là tín hiệu tốc độ. Thủ phạm hay gặp: ảnh không nén, font và mã theo dõi quá nhiều, video tự chạy. Sửa tốc độ là loại tối ưu hiếm hoi giúp mọi chiến dịch cùng lúc, vì mọi khách đều phải đi qua cửa đó.' },
  example:'10.000 lượt bấm nhưng chỉ 6.500 lượt xem: 35% người trả tiền đưa tới đã đi mất trước khi thấy gì. Shop nén ảnh còn 200KB, bỏ hai đoạn mã không dùng; trang hiện trong khoảng 2,5 giây. Lượt xem lên 8.500 trên 10.000 lượt bấm. Tỉ lệ mua trên người xem vẫn 2%, nhưng số đơn từ 130 lên 170 với cùng ngân sách quảng cáo.',
  takeaway:'So lượt bấm với lượt xem: phần chênh là tiền quảng cáo rơi trước cửa trang.',
  apply:'Mở trang đích của bạn trên điện thoại bằng 4G, bấm giờ tới khi thấy nội dung. Nói trong 60 giây: trang nặng vì đâu.',
  mistakes:['Thử tốc độ bằng máy tính ở văn phòng có wifi mạnh.','Nghĩ chênh lệch bấm và xem là "lỗi đo" rồi bỏ qua.'],
  q:[
  { type:'mcq', stem:'Đoán trước: 10.000 lượt bấm quảng cáo nhưng chỉ 6.500 lượt xem trang. Giải thích khả dĩ nhất là gì?',
    options:[{k:'a',t:'Nền tảng quảng cáo đếm ảo 35% lượt bấm để thu thêm tiền'},{k:'b',t:'Nhiều người rời đi khi trang còn đang tải nên không được ghi nhận'},
             {k:'c',t:'35% người bấm đã mua hàng ngay nên không cần xem trang'},{k:'d',t:'Công cụ phân tích web chỉ đếm người dùng máy tính, bỏ qua điện thoại'}],
    answer:'b', why:{a:'Có thể có bấm rác, nhưng mức chênh lớn kèm trang tải 6 giây chỉ thẳng vào tốc độ.',
      b:'Đúng. Mã đo chỉ chạy khi trang tải tới một mức nhất định; người thoát sớm biến mất khỏi báo cáo.',
      c:'Không thể mua mà không qua trang.',
      d:'Công cụ phân tích đo cả điện thoại.'} },
  { type:'mcq', stem:'Bạn có một ngày làm việc để cải thiện trang mỹ phẩm. Bạn ưu tiên làm gì trước?',
    options:[{k:'a',t:'Viết lại toàn bộ phần mô tả sản phẩm cho hấp dẫn hơn'},{k:'b',t:'Đổi màu nút mua từ xanh sang đỏ theo lời khuyên trên mạng'},
             {k:'c',t:'Nén sáu ảnh và gỡ các đoạn mã không còn dùng'},{k:'d',t:'Thêm một video giới thiệu sản phẩm tự chạy ở đầu trang cho sinh động'}],
    answer:'c', why:{a:'Mô tả hay cũng vô ích với 35% người không bao giờ thấy nó.',
      b:'Màu nút là chi tiết nhỏ; khách chưa tải được trang thì chưa thấy nút.',
      c:'Đúng. Tác động lên mọi khách, công sức ít — đúng việc nên làm trước.',
      d:'Video tự chạy làm trang còn nặng hơn.'} },
  { type:'calc', stem:'Với 10.000 lượt bấm, lượt xem tăng từ 6.500 lên 8.500 sau khi tăng tốc. Tỉ lệ mua trên người xem vẫn 2%. Số đơn tăng thêm là bao nhiêu?',
    unit:'đơn', ans:40, tol:0.5, wrong:[[2000,'QUEN_TI_LE_CHUYEN_DOI'],[170,'NHAM_SO_TUYET_DOI']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Trước: 6.500 × 2% = 130 đơn.','Sau: 8.500 × 2% = 170 đơn.','Tăng: <b>40 đơn</b> với cùng ngân sách.'] },
  { type:'calc', stem:'Shop trả 3.000đ mỗi lượt bấm, 10.000 lượt bấm. Chi phí quảng cáo trên mỗi đơn giảm bao nhiêu đồng khi số đơn đi từ 130 lên 170? (làm tròn tới đồng)',
    unit:'đồng', ans:54299, tol:5, wrong:[[40,'SAI_TINH_TOAN'],[176471,'NHAM_SO_TUYET_DOI']], errors:['SAI_TINH_TOAN'],
    steps:['Tổng chi: 10.000 × 3.000 = 30.000.000đ.','Trước: 30.000.000 ÷ 130 ≈ 230.769đ/đơn.','Sau: 30.000.000 ÷ 170 ≈ 176.471đ/đơn.','Giảm ≈ <b>54.299đ</b> mỗi đơn.'] },
  { type:'mcq', stem:'Bạn thử trang trên laptop ở văn phòng và thấy tải trong 1 giây. Kết luận nào đúng?',
    options:[{k:'a',t:'Trang đã nhanh, không cần sửa gì thêm về tốc độ nữa'},{k:'b',t:'Trang nhanh trên máy tính thì trên điện thoại cũng nhanh tương tự'},
             {k:'c',t:'Chưa đủ căn cứ; phải thử trên điện thoại dùng 4G như khách thật'},{k:'d',t:'Cần mua gói máy chủ đắt nhất để chắc chắn trang luôn nhanh'}],
    answer:'c', why:{a:'Điều kiện văn phòng không đại diện cho khách lướt quảng cáo trên điện thoại.',
      b:'Điện thoại yếu hơn và mạng di động chậm hơn; kết quả có thể khác xa.',
      c:'Đúng. Thử trong điều kiện của khách thật mới biết khách chờ bao lâu.',
      d:'Máy chủ đắt không sửa được ảnh 4MB; phải đo trước khi chi tiền.'} },
  { type:'mcq', stem:'Ba chiến dịch dẫn về cùng một trang đích chậm. Vì sao sửa tốc độ thường đáng làm trước khi tối ưu từng chiến dịch?',
    options:[{k:'a',t:'Vì tốc độ trang là yếu tố duy nhất quyết định doanh số'},{k:'b',t:'Vì một lần sửa giúp cả ba chiến dịch cùng lúc'},
             {k:'c',t:'Vì nền tảng quảng cáo sẽ tự động giảm giá bấm cho trang nhanh xuống một nửa'},{k:'d',t:'Vì chiến dịch thì không thể tối ưu được nữa sau khi đã chạy'}],
    answer:'b', why:{a:'Tốc độ quan trọng nhưng không phải yếu tố duy nhất.',
      b:'Đúng. Mọi khách đều qua cùng cửa; sửa cửa là lợi cho tất cả.',
      c:'Trải nghiệm trang có thể ảnh hưởng chi phí, nhưng không có con số cố định như vậy.',
      d:'Chiến dịch vẫn tối ưu được; chỉ là thứ tự ưu tiên.'} },
  { type:'mcq', stem:'Trang có 12 đoạn mã theo dõi do nhiều đợt thuê ngoài để lại. Nên làm gì?',
    options:[{k:'a',t:'Giữ hết, biết đâu sau này cần dùng lại dữ liệu từ đó'},{k:'b',t:'Xoá hết để trang nhanh nhất, kể cả mã đo chuyển đổi đang dùng'},
             {k:'c',t:'Thêm một đoạn mã nữa để đo xem các đoạn kia có chạy không'},{k:'d',t:'Kiểm kê, giữ mã đang dùng cho đo lường, gỡ phần không ai dùng'}],
    answer:'d', why:{a:'Mã không dùng vẫn làm chậm mọi lượt vào mỗi ngày.',
      b:'Xoá mã đo chuyển đổi thì mất khả năng tối ưu quảng cáo.',
      c:'Thêm mã là thêm tải.',
      d:'Đúng. Giữ cái có ích, bỏ cái chỉ tốn tốc độ.'} }
  ] },

/* ------------------------------------------------------------------ 05 */
{ id:'B:tu01-05', skill:'channel', read:'6 phút', t:'Vì sao thiết kế trên máy tính rồi mới "co lại" cho điện thoại là sai?',
  situation:'Một hãng balo làm trang đích trên màn hình máy tính: bảng so sánh ba mẫu nằm ngang, nút mua nhỏ ở góc phải, chữ mô tả cỡ 12. Báo cáo cho thấy 85% lượt vào là từ điện thoại. Tỉ lệ mua trên máy tính 3%, trên điện thoại chỉ 0,8%.',
  concept:{ name:'Thiết kế cho điện thoại trước (mobile first)',
    body:'Khi đa số khách tới từ điện thoại, bản điện thoại <b>là</b> trang chính, bản máy tính mới là bản phụ. Làm từ điện thoại lên buộc bạn chọn điều quan trọng nhất vì màn hình hẹp. Kiểm tra nhanh: chữ đọc được không cần phóng to; nút đủ lớn để bấm bằng ngón cái; bảng ngang được đổi thành thẻ xếp dọc; form dùng đúng bàn phím (số điện thoại bật bàn phím số). Chênh lệch tỉ lệ mua giữa hai thiết bị là chỉ báo trang điện thoại đang có vấn đề.' },
  example:'Hãng balo đổi bảng so sánh thành ba thẻ xếp dọc, nút mua to cố định ở đáy màn hình, chữ cỡ 16. Tỉ lệ mua trên điện thoại từ 0,8% lên 1,8%. Với 20.000 lượt vào mỗi tháng, 85% từ điện thoại là 17.000 lượt; số đơn từ điện thoại tăng từ 136 lên 306.',
  takeaway:'Khách ở đâu thì trang chính ở đó; hãy làm cho màn hình nhỏ trước.',
  apply:'Mở trang đích của bạn trên điện thoại, dùng một tay. Nói trong 60 giây: chỗ nào phải phóng to, chỗ nào khó bấm.',
  mistakes:['Duyệt thiết kế trên màn hình máy tính lớn trong phòng họp.','Đọc tỉ lệ mua chung mà không tách theo thiết bị.'],
  q:[
  { type:'mcq', stem:'Đoán trước: tỉ lệ mua trên máy tính 3%, trên điện thoại 0,8%. Cách đọc nào hợp lý nhất?',
    options:[{k:'a',t:'Khách dùng điện thoại vốn nghèo hơn nên ít mua hơn, không sửa được'},{k:'b',t:'Nên cắt quảng cáo trên điện thoại, dồn hết ngân sách cho máy tính'},
             {k:'c',t:'Trang trên điện thoại có thể đang cản trở việc mua'},{k:'d',t:'Chênh lệch vậy là bình thường nên không cần xem xét gì thêm'}],
    answer:'c', why:{a:'Giả định về túi tiền không có căn cứ; trải nghiệm trang là thứ kiểm tra được ngay.',
      b:'85% khách ở điện thoại; cắt đi là bỏ phần lớn thị trường.',
      c:'Đúng. Chênh lớn là lý do để mở trang trên điện thoại và tìm chỗ vướng.',
      d:'Có thể có chênh tự nhiên, nhưng gấp gần bốn lần thì đáng xem.'} },
  { type:'mcq', stem:'Bảng so sánh ba mẫu balo nằm ngang, trên điện thoại phải vuốt ngang mới xem hết. Bạn sửa gì?',
    options:[{k:'a',t:'Thu nhỏ bảng cho vừa màn hình điện thoại, chữ nhỏ đi một chút cũng được'},{k:'b',t:'Đổi thành ba thẻ xếp dọc, mỗi thẻ có ảnh, điểm khác biệt và nút'},
             {k:'c',t:'Bỏ bảng hoàn toàn và để khách tự tìm thông tin ở trang khác'},{k:'d',t:'Giữ bảng và thêm dòng chữ "Hãy xoay ngang điện thoại để xem"'}],
    answer:'b', why:{a:'Chữ nhỏ quá thì khách phải phóng to; thực chất là không đọc được.',
      b:'Đúng. Hợp chiều cuộn tự nhiên của điện thoại, mỗi mẫu tự đứng được.',
      c:'Khách cần so sánh để chọn; bỏ đi là đẩy họ đi chỗ khác.',
      d:'Bắt khách xoay máy là thêm việc; ít ai làm.'} },
  { type:'calc', stem:'20.000 lượt vào mỗi tháng, 85% từ điện thoại. Tỉ lệ mua trên điện thoại tăng từ 0,8% lên 1,8%. Số đơn từ điện thoại tăng thêm bao nhiêu?',
    unit:'đơn', ans:170, tol:0.5, wrong:[[200,'SAI_MAU_SO'],[306,'NHAM_SO_TUYET_DOI']], errors:['SAI_MAU_SO'],
    steps:['Lượt vào từ điện thoại: 20.000 × 85% = 17.000.','Trước: 17.000 × 0,8% = 136; sau: 17.000 × 1,8% = 306.','Tăng: <b>170 đơn</b>.'] },
  { type:'mcq', stem:'Ô nhập số điện thoại trong form bật bàn phím chữ cái trên điện thoại. Vì sao đáng sửa?',
    options:[{k:'a',t:'Khách phải chuyển bàn phím, thêm thao tác và dễ gõ sai'},{k:'b',t:'Vì bàn phím chữ cái làm trang tải chậm hơn bàn phím số'},
             {k:'c',t:'Vì hệ thống sẽ không lưu được số điện thoại nhập bằng bàn phím chữ'},{k:'d',t:'Vì bàn phím chữ cái chiếm ít chỗ nên khách không thấy nút gửi form'}],
    answer:'a', why:{a:'Đúng. Mỗi thao tác thừa trên điện thoại là một cơ hội bỏ cuộc.',
      b:'Bàn phím không ảnh hưởng tốc độ tải.',
      c:'Vẫn lưu được; vấn đề là trải nghiệm nhập.',
      d:'Bàn phím chữ không chiếm ít chỗ hơn; vấn đề không nằm ở đó.'} },
  { type:'mcq', stem:'Nút mua cố định ở đáy màn hình điện thoại có lợi gì?',
    options:[{k:'a',t:'Làm trang trông hiện đại hơn nên khách tin thương hiệu hơn'},{k:'b',t:'Giúp trang được các công cụ tìm kiếm xếp hạng cao hơn'},
             {k:'c',t:'Ép mọi khách phải quyết định mua trước khi kịp đọc xong mô tả sản phẩm'},{k:'d',t:'Khi khách sẵn sàng ở bất kỳ đoạn nào, nút đã nằm sẵn trong tầm ngón cái'}],
    answer:'d', why:{a:'Lợi ích chính là tiện, không phải vẻ hiện đại.',
      b:'Vị trí nút không phải yếu tố xếp hạng tìm kiếm đáng kể.',
      c:'Nút chỉ nằm sẵn; khách vẫn tự đọc tiếp nếu muốn.',
      d:'Đúng. Không phải cuộn đi tìm nút ở lúc quyết định.'} },
  { type:'mcq', stem:'Trong buổi duyệt thiết kế, cả nhóm xem trang trên màn chiếu lớn và khen đẹp. Bạn đề xuất gì?',
    options:[{k:'a',t:'Duyệt luôn vì cả nhóm đều thấy đẹp trên màn hình lớn'},{k:'b',t:'Chiếu thêm trên màn hình to hơn để thấy chi tiết rõ hơn'},
             {k:'c',t:'Mỗi người mở bản thử trên điện thoại của mình, dùng một tay'},{k:'d',t:'Gửi thiết kế cho khách hàng thân thiết bình chọn trên máy tính'}],
    answer:'c', why:{a:'Màn chiếu lớn không giống điều kiện của 85% khách.',
      b:'Màn to hơn càng xa thực tế.',
      c:'Đúng. Duyệt đúng thiết bị và tư thế khách dùng.',
      d:'Vẫn xem trên máy tính, lệch khỏi thực tế.'} },
  { type:'mcq', stem:'Trang có 60% lượt vào từ máy tính (sản phẩm là phần mềm kế toán cho doanh nghiệp). Nên làm gì?',
    options:[{k:'a',t:'Vẫn thiết kế điện thoại trước theo nguyên tắc, không cần xem số liệu'},{k:'b',t:'Bỏ hẳn bản điện thoại để tiết kiệm công sức làm trang'},
             {k:'c',t:'Chỉ làm bản điện thoại vì xu hướng chung là điện thoại'},{k:'d',t:'Ưu tiên trải nghiệm máy tính nhưng vẫn giữ bản điện thoại dùng tốt'}],
    answer:'d', why:{a:'Nguyên tắc gốc là làm theo nơi khách đang ở; ở đây khách chủ yếu ở máy tính.',
      b:'40% còn lại vẫn đáng kể.',
      c:'Xu hướng chung không thay cho số liệu của chính bạn.',
      d:'Đúng. Ưu tiên theo dữ liệu, không bỏ nhóm nào.'} }
  ] },

/* ------------------------------------------------------------------ 06 */
{ id:'B:tu01-06', skill:'brand', read:'6 phút', t:'Đánh giá của khách nên đặt ở đâu trên trang?',
  situation:'Một trang bán máy lọc không khí có 300 đánh giá 5 sao, ảnh khách dùng tại nhà và chứng nhận kiểm định. Tất cả nằm trong một mục "Khách hàng nói gì" ở cuối trang, sau phần thông số kỹ thuật dài. Nút "Mua ngay" nằm ở giữa trang, xung quanh chỉ có giá.',
  concept:{ name:'Bằng chứng đặt cạnh điểm quyết định',
    body:'Bằng chứng xã hội có tác dụng nhất <b>đúng lúc khách đang phân vân</b> — tức là ngay cạnh nút mua và cạnh giá. Để dồn hết ở cuối trang thì người quyết định sớm không thấy, người thấy thì đã đọc quá nhiều. Cách làm: một dòng ngắn ngay dưới nút (số sao, số đánh giá), một hai trích dẫn cụ thể gần giá, chứng nhận cạnh lời hứa mà nó chứng minh. Bằng chứng cụ thể (phòng 25m², con bị dị ứng) mạnh hơn lời khen chung.' },
  example:'Trang đặt ngay dưới nút: "4,8/5 từ 300 gia đình". Cạnh giá: trích dẫn "Phòng ngủ 20m², bé nhà mình hết hắt hơi buổi sáng sau một tuần". Chứng nhận kiểm định đặt cạnh câu "lọc bụi mịn PM2.5". Trên 8.000 lượt vào, tỉ lệ bấm nút từ 5% lên 6,5%, tức từ 400 lên 520 lượt bấm mua.',
  takeaway:'Đặt bằng chứng ở nơi khách phân vân, không phải nơi còn chỗ trống.',
  apply:'Tìm trên một trang bán hàng chỗ khách dễ phân vân nhất. Nói trong 60 giây: bằng chứng nào nên đặt ở đó.',
  mistakes:['Gom mọi đánh giá vào một mục riêng ở cuối trang.','Chọn lời khen chung chung thay vì câu có tình huống cụ thể.'],
  q:[
  { type:'mcq', stem:'Đoán trước: chuyển một dòng "4,8/5 từ 300 gia đình" lên ngay dưới nút mua. Tác động hợp lý nhất?',
    options:[{k:'a',t:'Không thay đổi vì khách muốn xem đánh giá sẽ tự cuộn xuống tìm'},{k:'b',t:'Có thể tăng tỉ lệ bấm vì trấn an đúng lúc khách đang cân nhắc'},
             {k:'c',t:'Giảm tỉ lệ bấm vì làm khu vực nút mua bị rối mắt hơn trước'},{k:'d',t:'Tăng mạnh gấp đôi ngay lập tức với mọi loại sản phẩm'}],
    answer:'b', why:{a:'Người đang phân vân ít khi đi tìm; họ dễ rời trang hơn.',
      b:'Đúng. Bằng chứng gần điểm quyết định giảm lo lắng đúng thời điểm.',
      c:'Một dòng ngắn không gây rối; một khối dài mới gây rối.',
      d:'Không có mức tăng cố định; cần đo.'} },
  { type:'mcq', stem:'Bạn chỉ được chọn một trích dẫn đặt cạnh giá máy lọc không khí. Bạn chọn câu nào?',
    options:[{k:'a',t:'"Sản phẩm tuyệt vời, rất đáng tiền, sẽ ủng hộ shop dài dài!"'},{k:'b',t:'"Giao hàng nhanh, đóng gói cẩn thận, shipper thân thiện"'},
             {k:'c',t:'"Phòng 20m², bé hết hắt hơi buổi sáng sau một tuần"'},{k:'d',t:'"Máy màu trắng rất đẹp, hợp với nội thất phòng khách nhà mình"'}],
    answer:'c', why:{a:'Lời khen chung, không chứng minh công dụng.',
      b:'Nói về giao hàng, không nói máy có lọc tốt không.',
      c:'Đúng. Có bối cảnh cụ thể và chứng minh đúng lời hứa chính của sản phẩm.',
      d:'Màu sắc không phải lý do chính người ta mua máy lọc.'} },
  { type:'calc', stem:'Trang có 8.000 lượt vào. Tỉ lệ bấm nút mua tăng từ 5% lên 6,5%. Số lượt bấm mua tăng bao nhiêu phần trăm so với trước?',
    unit:'%', ans:30, tol:0.1, wrong:[[1.5,'NHAM_DIEM_PHAN_TRAM'],[120,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Trước: 8.000 × 5% = 400; sau: 8.000 × 6,5% = 520.','Tăng tương đối: (520 − 400) ÷ 400 = <b>30%</b>.','Chú ý: 1,5 là điểm phần trăm, không phải mức tăng tương đối.'] },
  { type:'mcq', stem:'Chứng nhận kiểm định lọc bụi mịn nên đặt ở đâu?',
    options:[{k:'a',t:'Cạnh câu hứa "lọc bụi mịn PM2.5" mà nó chứng minh'},{k:'b',t:'Ở cuối trang, trong một mục riêng tên "Giấy tờ pháp lý"'},
             {k:'c',t:'Ở màn hình đầu, thay cho ảnh sản phẩm để tạo uy tín'},{k:'d',t:'Chỉ gửi cho khách khi họ nhắn tin hỏi, tránh làm dài trang'}],
    answer:'a', why:{a:'Đúng. Lời hứa và bằng chứng đứng cạnh nhau thì khách tin ngay.',
      b:'Tách xa khỏi lời hứa, ít người nối được hai thứ.',
      c:'Màn hình đầu cần sản phẩm; chứng nhận là phần củng cố.',
      d:'Nhiều người không nhắn tin hỏi mà rời trang luôn.'} },
  { type:'mcq', stem:'Trang có ghi "Hơn 10.000 khách tin dùng" nhưng không có đánh giá hay ảnh nào. Vấn đề là gì?',
    options:[{k:'a',t:'Con số quá lớn khiến khách thấy thương hiệu đại trà'},{k:'b',t:'Con số nên được làm tròn thành 10.000 để dễ nhớ hơn'},
             {k:'c',t:'Chỉ nên nói số khách khi đã vượt mốc 100.000 người'},{k:'d',t:'Con số không kèm bằng chứng cụ thể thì khó tin'}],
    answer:'d', why:{a:'Số lớn thường giúp; vấn đề là không kiểm chứng được.',
      b:'Làm tròn không giải quyết độ tin.',
      c:'Không có mốc bắt buộc; quan trọng là thật và có bằng chứng.',
      d:'Đúng. Khách cần thấy vài người thật, tình huống thật để tin con số.'} },
  { type:'mcq', stem:'Một khách để lại đánh giá 2 sao chê máy hơi ồn ở mức cao nhất. Nên xử lý trên trang thế nào?',
    options:[{k:'a',t:'Xoá đánh giá đó để trang chỉ còn toàn 5 sao cho đẹp'},{k:'b',t:'Để nguyên kèm phản hồi: chế độ ngủ chạy êm, mức cao dùng khi vắng người'},
             {k:'c',t:'Đưa đánh giá đó lên đầu trang để chứng tỏ sự minh bạch tuyệt đối'},{k:'d',t:'Ẩn toàn bộ phần đánh giá cho tới khi không còn đánh giá xấu nào'}],
    answer:'b', why:{a:'Toàn 5 sao dễ bị nghi ngờ; xoá chê cũng làm mất lòng tin nếu bị phát hiện.',
      b:'Đúng. Một lời chê có câu trả lời rõ còn làm các lời khen đáng tin hơn.',
      c:'Minh bạch không có nghĩa là đưa lời chê lên vị trí đẹp nhất.',
      d:'Mất luôn toàn bộ bằng chứng tốt.'} },
  { type:'mcq', stem:'Trang bán khoá học online muốn đặt bằng chứng cạnh nút đăng ký. Loại nào hợp nhất?',
    options:[{k:'a',t:'Ảnh văn phòng công ty và đội ngũ nhân viên đang họp'},{k:'b',t:'Danh sách các đối tác logo lớn mà công ty từng làm sự kiện'},
             {k:'c',t:'Kết quả cụ thể của một học viên cũ, kèm tên và ảnh thật'},{k:'d',t:'Số lượt thích của fanpage và số người theo dõi kênh video'}],
    answer:'c', why:{a:'Không chứng minh khoá học giúp được gì.',
      b:'Logo sự kiện không liên quan tới kết quả học.',
      c:'Đúng. Người học cần thấy người giống mình đạt được kết quả.',
      d:'Lượt thích nói về độ nổi, không nói về chất lượng khoá học.'} }
  ] },

/* ------------------------------------------------------------------ 07 */
{ id:'B:tu01-07', skill:'insight', read:'7 phút', t:'Khách đã thích sản phẩm, sao vẫn không bấm mua?',
  situation:'Một thương hiệu giày da nam bán trên website. Ghi hình phiên cho thấy nhiều khách xem kỹ ảnh, chọn size, rồi cuộn tìm gì đó, mở trang "Chính sách" trong tab khác và thoát. Chính sách đổi size, phí ship và bảo hành chỉ có trong một trang riêng dài 2.000 chữ.',
  concept:{ name:'Nỗi lo cuối cùng',
    body:'Sát lúc trả tiền, khách không còn hỏi "có đẹp không" mà hỏi "<b>lỡ không vừa thì sao, ship bao nhiêu, hỏng thì ai lo</b>". Đó là nỗi lo cuối cùng. Nếu câu trả lời không nằm ngay cạnh nút mua, khách phải đi tìm — và nhiều người không quay lại. Cách làm: ba dòng ngắn dưới nút, mỗi dòng trả lời một nỗi lo, như "Đổi size miễn phí 7 ngày", "Ship 25.000đ, miễn phí từ 500.000đ", "Bảo hành keo đế 12 tháng". Chỉ hứa điều thật sự làm được.' },
  example:'Thương hiệu giày thêm ba dòng dưới nút "Thêm vào giỏ". Trong 2.000 người chọn size mỗi tháng, tỉ lệ bấm thêm vào giỏ tăng từ 20% lên 26%. Thêm 120 người vào giỏ. Số đơn đổi size tăng nhẹ, mỗi lần đổi tốn khoảng 50.000đ phí vận chuyển hai chiều, nhưng thấp hơn nhiều so với lợi nhuận từ đơn tăng thêm.',
  takeaway:'Trả lời nỗi lo cuối cùng ngay cạnh nút mua, đừng bắt khách đi tìm.',
  apply:'Nghĩ về lần gần nhất bạn bỏ giỏ hàng. Nói trong 60 giây: nỗi lo cuối cùng là gì, trang nên trả lời nó ở đâu.',
  mistakes:['Giấu chính sách trong trang riêng vì sợ khách lạm dụng đổi trả.','Viết chính sách bằng câu pháp lý dài thay vì một dòng dễ hiểu.'],
  q:[
  { type:'mcq', stem:'Đoán trước: khách chọn size xong rồi mở trang "Chính sách" và thoát. Điều đó gợi ý gì?',
    options:[{k:'a',t:'Họ chỉ tò mò về công ty, không có ý định mua ngay từ đầu'},{k:'b',t:'Giá giày quá cao so với thị trường nên họ bỏ đi'},
             {k:'c',t:'Ảnh sản phẩm chưa đủ đẹp để thuyết phục họ mua hàng'},{k:'d',t:'Họ đang tìm câu trả lời cho nỗi lo đổi size, phí ship'}],
    answer:'d', why:{a:'Người chỉ tò mò hiếm khi chọn size.',
      b:'Họ đã xem giá rồi mới chọn size; hành vi đi tìm chính sách chỉ vào nỗi lo khác.',
      c:'Họ đã xem kỹ ảnh và chọn size; ảnh không phải điểm vướng.',
      d:'Đúng. Hành động cuối trước khi thoát cho biết họ đang lo điều gì.'} },
  { type:'mcq', stem:'Bạn chỉ được thêm ba dòng dưới nút mua giày. Bạn chọn ba dòng nào?',
    options:[{k:'a',t:'Đổi size miễn phí 7 ngày · Ship 25.000đ, miễn phí từ 500.000đ · Bảo hành keo đế 12 tháng'},{k:'b',t:'Da bò thật 100% · Thiết kế theo phong cách Ý · Được nhiều người nổi tiếng yêu thích'},
             {k:'c',t:'Hotline, email và địa chỉ showroom để khách tự liên hệ hỏi thêm'},{k:'d',t:'Mã giảm 10% · Quà tặng tất · Tích điểm thành viên cho lần mua sau'}],
    answer:'a', why:{a:'Đúng. Mỗi dòng trả lời đúng một nỗi lo cuối cùng.',
      b:'Đây là lý do thích sản phẩm; khách đã thích rồi, cái họ thiếu là sự an tâm.',
      c:'Bắt khách tự hỏi là thêm một bước.',
      d:'Khuyến mãi không trả lời chuyện không vừa size.'} },
  { type:'calc', stem:'2.000 người chọn size mỗi tháng. Tỉ lệ thêm vào giỏ tăng từ 20% lên 26%. Có thêm bao nhiêu người thêm vào giỏ?',
    unit:'người', ans:120, tol:0.5, wrong:[[6,'NHAM_DIEM_PHAN_TRAM'],[520,'NHAM_SO_TUYET_DOI']], errors:['NHAM_DIEM_PHAN_TRAM'],
    steps:['Trước: 2.000 × 20% = 400.','Sau: 2.000 × 26% = 520.','Thêm: <b>120 người</b>.'] },
  { type:'calc', stem:'Trong 120 người thêm vào giỏ, 60% đặt hàng thành công; mỗi đơn lãi gộp 300.000đ. 10% số đơn tăng thêm này phải đổi size, mỗi lần tốn 50.000đ. Lợi nhuận tăng thêm là bao nhiêu đồng?',
    unit:'đồng', ans:21240000, tol:1000, wrong:[[21600000,'QUEN_CHI_PHI_BIEN_DOI'],[36000000,'QUEN_TI_LE_CHUYEN_DOI']], errors:['QUEN_CHI_PHI_BIEN_DOI'],
    steps:['Đơn thêm: 120 × 60% = 72 đơn.','Lãi gộp: 72 × 300.000 = 21.600.000đ.','Đổi size: 72 × 10% = 7,2 lần × 50.000 = 360.000đ.','Lợi nhuận thêm: 21.600.000 − 360.000 = <b>21.240.000đ</b>.'] },
  { type:'mcq', stem:'Chủ shop lo "ghi đổi miễn phí thì khách lạm dụng". Cách trả lời hợp lý nhất?',
    options:[{k:'a',t:'Đúng vậy, nên giấu kỹ chính sách đổi trả trong trang riêng'},{k:'b',t:'Đặt điều kiện rõ (7 ngày, còn tem) và theo dõi tỉ lệ đổi'},
             {k:'c',t:'Bỏ hoàn toàn chính sách đổi size để không phát sinh chi phí'},{k:'d',t:'Hứa đổi trả trọn đời mọi lý do để vượt đối thủ trong ngành'}],
    answer:'b', why:{a:'Giấu đi thì mất khách lo lắng, trong khi người muốn lạm dụng vẫn tìm ra.',
      b:'Đúng. Điều kiện rõ hạn chế lạm dụng; số liệu cho biết chi phí thật có đáng lo không.',
      c:'Giày cần thử size; không có đổi thì nhiều người không dám mua online.',
      d:'Hứa quá mức làm chi phí khó kiểm soát; chỉ hứa điều làm được.'} },
  { type:'mcq', stem:'Một trang bán đồ nội thất lớn (sofa, giường). Nỗi lo cuối cùng nào nên được trả lời cạnh nút mua?',
    options:[{k:'a',t:'Màu sắc có hợp phong thuỷ tuổi của khách hay không'},{k:'b',t:'Lịch sử thành lập xưởng sản xuất và số năm kinh nghiệm'},
             {k:'c',t:'Giao lắp tận nhà, phí vận chuyển và thời gian giao'},{k:'d',t:'Số lượng người theo dõi thương hiệu trên các mạng xã hội'}],
    answer:'c', why:{a:'Có thể là câu hỏi của một số người, nhưng không phải nỗi lo chung với hàng cồng kềnh.',
      b:'Củng cố niềm tin chung, không trả lời chuyện hậu cần.',
      c:'Đúng. Hàng to nặng thì "ai chở, ai lắp, bao lâu" là câu hỏi sát lúc trả tiền.',
      d:'Không liên quan tới việc nhận hàng.'} },
  { type:'mcq', stem:'Chính sách hiện viết: "Quý khách được quyền yêu cầu đổi sản phẩm trong thời hạn quy định theo điều khoản 4.2". Nên sửa thế nào?',
    options:[{k:'a',t:'Giữ nguyên vì văn phong pháp lý tạo cảm giác uy tín'},{k:'b',t:'Thêm đường dẫn tới điều khoản 4.2 cho khách tự đọc kỹ'},
             {k:'c',t:'Viết thêm hai đoạn giải thích chi tiết từng trường hợp ngoại lệ'},{k:'d',t:'Viết lại thành "Đổi size miễn phí trong 7 ngày"'}],
    answer:'d', why:{a:'Khách không hiểu thì không được trấn an.',
      b:'Bắt khách đi đọc thêm là thêm bước.',
      c:'Chi tiết để ở trang chính sách; cạnh nút cần một dòng.',
      d:'Đúng. Ngắn, cụ thể, đọc một lần là hiểu.'} }
  ] },

/* ------------------------------------------------------------------ 08 */
{ id:'B:tu01-08', skill:'creative', read:'6 phút', t:'Nút "Gửi" và nút "Nhận lịch tư vấn miễn phí" khác nhau thế nào?',
  situation:'Một phòng khám nha khoa có trang đích quảng cáo niềng răng. Cuối form là nút xám chữ "Gửi", cùng màu với nền. Phía trên còn có nút "Xem thêm" màu cam nổi bật dẫn sang trang bảng giá. Nhiều khách bấm "Xem thêm" và không quay lại form.',
  concept:{ name:'Nút kêu gọi hành động rõ',
    body:'Nút tốt trả lời hai câu: <b>bấm thì tôi được gì</b>, và nó có nổi bật nhất trang không. Chữ trên nút nên nói kết quả cho khách ("Nhận lịch tư vấn miễn phí") thay vì thao tác của máy ("Gửi"). Màu nút chính phải tương phản với nền và là màu mạnh nhất trang; các nút phụ nhạt hơn. Một câu nhỏ dưới nút gỡ lo ("Không mất phí, gọi lại trong 30 phút") thường giúp thêm. Màu cụ thể không có phép màu; cái quyết định là độ tương phản và thứ bậc.' },
  example:'Phòng khám đổi nút thành màu cam đậm, chữ "Nhận lịch tư vấn miễn phí", dưới có dòng "Bác sĩ gọi lại trong 30 phút". Nút "Xem thêm" chuyển thành chữ gạch chân nhỏ. Trên 3.000 người xem form, tỉ lệ gửi từ 4% lên 6%: từ 120 lên 180 lịch hẹn mỗi tháng.',
  takeaway:'Nút chính phải nổi nhất trang và nói điều khách nhận được khi bấm.',
  apply:'Tìm ba nút kêu gọi trên các trang bạn hay vào. Nói trong 60 giây: nút nào nói rõ khách nhận gì, nút nào chỉ nói thao tác.',
  mistakes:['Để nút phụ nổi bật hơn nút chính.','Tranh luận màu xanh hay đỏ thay vì nhìn độ tương phản và chữ trên nút.'],
  q:[
  { type:'mcq', stem:'Đoán trước: nút "Xem thêm" cam nổi bật, nút "Gửi" xám nhạt. Khách có xu hướng gì?',
    options:[{k:'a',t:'Bấm vào nút nổi bật nhất, kể cả khi nó dẫn ra khỏi form'},{k:'b',t:'Đọc kỹ hết mọi nút rồi mới chọn nút đúng với mục đích'},
             {k:'c',t:'Bỏ qua cả hai nút vì màu sắc không có tác động gì'},{k:'d',t:'Luôn bấm vào nút ở cuối trang vì đó là thói quen chung'}],
    answer:'a', why:{a:'Đúng. Mắt đi theo thứ bậc thị giác; nút nổi nhất được bấm nhiều nhất.',
      b:'Khách lướt nhanh, ít ai đọc kỹ mọi nút.',
      c:'Độ nổi bật ảnh hưởng rõ tới nơi mắt dừng lại.',
      d:'Không có thói quen chung như vậy; họ bấm cái nổi bật.'} },
  { type:'mcq', stem:'Bạn chọn chữ nào cho nút chính của form niềng răng?',
    options:[{k:'a',t:'Gửi thông tin'},{k:'b',t:'Đăng ký ngay hôm nay'},
             {k:'c',t:'Nhận lịch tư vấn miễn phí'},{k:'d',t:'Bấm vào đây để hoàn tất việc gửi form'}],
    answer:'c', why:{a:'Nói thao tác, không nói khách được gì.',
      b:'Có thúc giục nhưng không nói đăng ký để nhận gì.',
      c:'Đúng. Nói thẳng kết quả khách nhận được và gỡ nỗi lo về phí.',
      d:'Dài mà vẫn chỉ nói thao tác.'} },
  { type:'calc', stem:'3.000 người xem form mỗi tháng, tỉ lệ gửi tăng từ 4% lên 6%. Mỗi lịch hẹn có 25% đến khám và bắt đầu niềng. Số ca niềng tăng thêm mỗi tháng là bao nhiêu?',
    unit:'ca', ans:15, tol:0.1, wrong:[[60,'QUEN_TI_LE_CHUYEN_DOI'],[45,'NHAM_SO_TUYET_DOI']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Lịch hẹn thêm: 3.000 × (6% − 4%) = 60.','Ca niềng thêm: 60 × 25% = <b>15 ca</b>.'] },
  { type:'mcq', stem:'Đồng nghiệp muốn chạy thử "nút đỏ hay nút xanh" vì đọc được bài nói nút đỏ luôn thắng. Bạn phản hồi thế nào?',
    options:[{k:'a',t:'Đồng ý dùng nút đỏ luôn, vì bài viết đã có kết luận sẵn rồi'},{k:'b',t:'Màu nào cũng được, miễn là phải giống màu logo thương hiệu'},
             {k:'c',t:'Chọn màu xanh vì xanh là màu của sự tin cậy trong ngành y tế'},{k:'d',t:'Màu thắng là màu tương phản nhất với nền, và nút phụ phải nhạt hơn'}],
    answer:'d', why:{a:'Kết quả ở trang khác, nền khác không áp dụng nguyên.',
      b:'Màu logo có thể chìm vào nền nếu trang cũng dùng màu đó.',
      c:'Ý nghĩa màu sắc yếu hơn nhiều so với việc nút có nổi bật hay không.',
      d:'Đúng. Độ tương phản và thứ bậc quyết định, không phải một màu thần kỳ.'} },
  { type:'mcq', stem:'Dòng chữ nhỏ nào dưới nút giúp gỡ lo tốt nhất cho form tư vấn niềng răng?',
    options:[{k:'a',t:'Thông tin của bạn sẽ được xử lý theo điều khoản sử dụng dịch vụ'},{k:'b',t:'Không mất phí, bác sĩ gọi lại trong 30 phút'},
             {k:'c',t:'Hơn 15 năm kinh nghiệm trong lĩnh vực nha khoa thẩm mỹ'},{k:'d',t:'Ưu đãi có hạn, nhanh tay kẻo lỡ cơ hội vàng hôm nay'}],
    answer:'b', why:{a:'Câu pháp lý khó hiểu, không trấn an.',
      b:'Đúng. Trả lời hai nỗi lo: có tốn tiền không, bao giờ được liên hệ.',
      c:'Là bằng chứng uy tín, không trả lời chuyện gì xảy ra sau khi bấm.',
      d:'Thúc ép có thể làm khách nghi ngờ thay vì yên tâm.'} },
  { type:'mcq', stem:'Trang có ba nút cùng cỡ, cùng màu: "Đặt lịch", "Xem bảng giá", "Gọi ngay". Vấn đề chính?',
    options:[{k:'a',t:'Thiếu nút thứ tư để khách có thêm lựa chọn phù hợp'},{k:'b',t:'Ba nút cùng màu làm trang trông thiếu sáng tạo, nhàm chán'},
             {k:'c',t:'Không có thứ bậc, khách không biết nên bấm cái nào'},{k:'d',t:'Chữ trên ba nút quá ngắn nên khách không hiểu nghĩa'}],
    answer:'c', why:{a:'Thêm nút chỉ làm tình trạng nặng hơn.',
      b:'Vấn đề không phải thẩm mỹ mà là hướng dẫn hành động.',
      c:'Đúng. Phải có một nút chính nổi nhất; nút khác lùi xuống.',
      d:'Chữ hiểu được; vấn đề là không có nút nào dẫn dắt.'} },
  { type:'mcq', stem:'Nút đặt lịch trên điện thoại chỉ cao khoảng 24 pixel, nằm sát một đường dẫn khác. Nên làm gì?',
    options:[{k:'a',t:'Giữ nguyên vì nút nhỏ trông tinh tế và sang hơn'},{k:'b',t:'Làm nút to đủ bấm bằng ngón cái và cách xa đường dẫn khác'},
             {k:'c',t:'Đổi sang màu nhấp nháy để khách chú ý tới nút nhỏ'},{k:'d',t:'Thêm hướng dẫn "phóng to trang để bấm nút dễ hơn"'}],
    answer:'b', why:{a:'Nút nhỏ dễ bấm nhầm, khách bực và bỏ đi.',
      b:'Đúng. Dễ bấm đúng là điều kiện cơ bản trên điện thoại.',
      c:'Nhấp nháy gây khó chịu và không sửa được chuyện bấm nhầm.',
      d:'Bắt khách phóng to là thêm việc.'} }
  ] },

/* ------------------------------------------------------------------ 09 */
{ id:'B:tu01-09', skill:'measure', read:'7 phút', t:'Bản đồ nhiệt và ghi hình phiên cho biết điều gì?',
  situation:'Một shop trà sữa đóng chai bán online gắn công cụ bản đồ nhiệt và ghi hình phiên. Bản đồ nhiệt cho thấy nhiều lượt bấm vào ảnh sản phẩm dù ảnh không bấm được. Bản đồ cuộn cho thấy chỉ 30% người cuộn tới phần bảng giá combo. Ghi hình phiên cho thấy nhiều người bấm liên tục vào ô chọn vị.',
  concept:{ name:'Đọc bản đồ nhiệt và ghi hình phiên',
    body:'Số liệu cho biết <b>bao nhiêu</b> người rời đi; bản đồ nhiệt và ghi hình phiên gợi ý <b>vì sao</b>. Ba tín hiệu hay gặp: bấm vào thứ không bấm được (khách mong nó làm gì đó, như phóng to ảnh); bấm liên tục ở một chỗ (có lỗi hoặc phản hồi chậm); bản đồ cuộn tụt mạnh ở một đoạn (nội dung quan trọng nằm quá sâu). Xem đủ nhiều phiên để thấy khuôn mẫu, đừng kết luận từ một hai người. Đây là nguồn ý tưởng để thử, không phải bằng chứng cuối cùng.' },
  example:'Shop cho ảnh bấm phóng to được, sửa ô chọn vị bị lỗi trên một số điện thoại, đưa bảng combo lên trên phần câu chuyện thương hiệu. Tỷ lệ người thấy bảng combo từ 30% lên 70%. Trong 6.000 lượt vào mỗi tháng, số người thấy bảng combo tăng từ 1.800 lên 4.200; với 5% trong số người thấy chọn mua combo, số combo bán từ 90 lên 210.',
  takeaway:'Số liệu nói bao nhiêu; bản đồ nhiệt và ghi hình phiên gợi ý vì sao.',
  apply:'Xem mười phiên ghi hình của trang bạn phụ trách (hoặc tưởng tượng mười khách). Nói trong 60 giây: khuôn mẫu nào lặp lại, bạn muốn thử sửa gì.',
  mistakes:['Kết luận từ một hai phiên ghi hình gây ấn tượng mạnh.','Coi bản đồ nhiệt là bằng chứng cuối cùng mà không đo lại sau khi sửa.'],
  q:[
  { type:'mcq', stem:'Đoán trước: nhiều người bấm vào ảnh sản phẩm dù ảnh không bấm được. Điều đó gợi ý gì?',
    options:[{k:'a',t:'Khách bấm nhầm do tay run, không có ý nghĩa gì đáng kể'},{k:'b',t:'Ảnh sản phẩm xấu nên khách bấm vào để bày tỏ không hài lòng'},
             {k:'c',t:'Khách muốn xem ảnh to hơn hoặc xem thêm chi tiết'},{k:'d',t:'Bản đồ nhiệt bị lỗi, nên gỡ công cụ đo ra khỏi trang ngay'}],
    answer:'c', why:{a:'Một hai lần có thể nhầm; nhiều người lặp lại là có chủ đích.',
      b:'Không ai bấm vào ảnh để bày tỏ không hài lòng.',
      c:'Đúng. Bấm vào thứ không bấm được cho thấy khách kỳ vọng một hành động ở đó.',
      d:'Không có dấu hiệu công cụ lỗi; hành vi này rất phổ biến.'} },
  { type:'mcq', stem:'Bạn thấy ba tín hiệu: bấm vào ảnh, bấm liên tục vào ô chọn vị, 30% cuộn tới bảng combo. Bạn sửa gì trước?',
    options:[{k:'a',t:'Ô chọn vị bị lỗi, vì khách muốn mua mà không chọn được'},{k:'b',t:'Cho phóng to ảnh, vì đó là tín hiệu có nhiều lượt bấm nhất'},
             {k:'c',t:'Đổi toàn bộ giao diện trang sang mẫu mới đang thịnh hành'},{k:'d',t:'Viết thêm phần câu chuyện thương hiệu để khách ở lại lâu hơn'}],
    answer:'a', why:{a:'Đúng. Lỗi chặn đường mua của người đã quyết định là thiệt hại trực tiếp nhất.',
      b:'Nhiều lượt bấm nhưng mức thiệt hại thấp hơn một lỗi chặn mua.',
      c:'Làm lại hết là tốn công, lại không nhắm vào vấn đề cụ thể.',
      d:'Câu chuyện dài hơn càng đẩy bảng combo xuống sâu.'} },
  { type:'calc', stem:'6.000 lượt vào mỗi tháng. Tỉ lệ người thấy bảng combo tăng từ 30% lên 70%. 5% người thấy bảng sẽ mua combo. Số combo bán thêm mỗi tháng?',
    unit:'combo', ans:120, tol:0.5, wrong:[[2400,'QUEN_TI_LE_CHUYEN_DOI'],[2,'NHAM_DIEM_PHAN_TRAM']], errors:['QUEN_TI_LE_CHUYEN_DOI'],
    steps:['Người thấy thêm: 6.000 × (70% − 30%) = 2.400.','Combo thêm: 2.400 × 5% = <b>120 combo</b>.'] },
  { type:'mcq', stem:'Bạn xem hai phiên ghi hình, cả hai khách đều thoát ở phần phí ship. Kết luận đúng là gì?',
    options:[{k:'a',t:'Phí ship chắc chắn là lý do chính khiến khách bỏ trang'},{k:'b',t:'Phải bỏ phí ship ngay lập tức để giữ khách lại'},
             {k:'c',t:'Ghi hình phiên vô dụng vì hai người không nói lên điều gì'},{k:'d',t:'Đáng nghi; cần xem thêm nhiều phiên để thấy khuôn mẫu'}],
    answer:'d', why:{a:'Hai phiên chưa đủ để kết luận chắc chắn.',
      b:'Hành động lớn cần căn cứ lớn hơn hai phiên.',
      c:'Hai phiên chưa đủ kết luận, nhưng đủ để đặt câu hỏi.',
      d:'Đúng. Mẫu nhỏ gợi giả thuyết; cần đủ phiên để chắc đó là khuôn mẫu.'} },
  { type:'mcq', stem:'Bản đồ cuộn cho thấy 70% người rời trước phần bảng giá combo. Cách sửa hợp lý nhất?',
    options:[{k:'a',t:'Thêm mũi tên chỉ xuống và dòng "Cuộn xuống để xem ưu đãi"'},{k:'b',t:'Đưa bảng combo lên cao hơn, trên các phần ít quan trọng'},
             {k:'c',t:'Chia trang thành ba trang con để mỗi trang ngắn hơn'},{k:'d',t:'Tăng cỡ chữ toàn trang để khách đọc chậm lại và cuộn tiếp'}],
    answer:'b', why:{a:'Mời cuộn không bằng đặt thứ quan trọng ở chỗ khách đã nhìn.',
      b:'Đúng. Nội dung quan trọng phải ở trong vùng đa số khách tới được.',
      c:'Thêm trang là thêm bước bấm và thêm chỗ rơi.',
      d:'Chữ to hơn làm trang dài hơn, bảng combo càng sâu.'} },
  { type:'mcq', stem:'Sau khi sửa theo bản đồ nhiệt, bước tiếp theo nên là gì?',
    options:[{k:'a',t:'Đo lại tỉ lệ chuyển đổi để biết thay đổi có thật sự giúp'},{k:'b',t:'Gỡ công cụ bản đồ nhiệt vì đã dùng xong, không cần nữa'},
             {k:'c',t:'Công bố kết quả thành công ngay vì bản đồ nhiệt đã chỉ rõ'},{k:'d',t:'Sửa tiếp toàn bộ mọi chỗ có ít lượt bấm trên bản đồ nhiệt'}],
    answer:'a', why:{a:'Đúng. Bản đồ nhiệt cho ý tưởng; số liệu sau khi sửa mới xác nhận.',
      b:'Trang còn thay đổi; công cụ vẫn hữu ích để theo dõi.',
      c:'Chưa đo thì chưa biết có thành công.',
      d:'Ít lượt bấm không có nghĩa là có vấn đề; nhiều vùng vốn để đọc.'} },
  { type:'mcq', stem:'Ghi hình phiên có thể ghi lại cả thông tin khách gõ vào form. Nên cấu hình thế nào?',
    options:[{k:'a',t:'Ghi đầy đủ mọi thứ khách gõ để phân tích cho chính xác nhất'},{k:'b',t:'Tắt hẳn ghi hình phiên vì mọi dạng ghi hình đều không được phép'},
             {k:'c',t:'Chỉ ghi các ô số điện thoại và địa chỉ vì đó là nơi khách hay bỏ'},{k:'d',t:'Che các ô nhập thông tin cá nhân, chỉ ghi thao tác và vị trí bấm'}],
    answer:'d', why:{a:'Ghi thông tin cá nhân không cần thiết cho việc tối ưu và tạo rủi ro.',
      b:'Ghi hành vi mà không lấy dữ liệu cá nhân vẫn là cách làm phổ biến.',
      c:'Đó chính là thông tin cá nhân cần được che.',
      d:'Đúng. Đủ để thấy hành vi mà không cần biết khách gõ gì.'} }
  ] },

/* ------------------------------------------------------------------ 10 */
{ id:'B:tu01-10', skill:'measure', read:'7 phút', t:'Mười việc cần sửa trên trang — làm cái nào trước?',
  situation:'Sau một tuần soi trang đích bán nồi chiên không dầu, nhóm có danh sách mười việc: nén ảnh, sửa nút đặt hàng lỗi trên iPhone, viết lại toàn bộ mô tả, thêm video, đổi font, rút form từ 7 xuống 3 trường, thêm đánh giá cạnh nút, làm lại cả giao diện… Chỉ có một người lập trình, làm 10 ngày mỗi tháng.',
  concept:{ name:'Ưu tiên theo tác động × công sức',
    body:'Chấm mỗi việc hai điểm: <b>tác động</b> (bao nhiêu khách bị ảnh hưởng, ảnh hưởng nặng tới đâu) và <b>công sức</b> (mấy ngày làm). Lấy tác động chia công sức để xếp hạng. Làm trước nhóm tác động cao – công sức thấp; nhóm tác động cao – công sức cao lên kế hoạch; nhóm tác động thấp thì để sau. Lỗi chặn mua luôn đứng đầu vì tác động là toàn bộ đơn bị mất. Điểm chấm là ước lượng, nên ghi lý do và đo lại sau khi làm.' },
  example:'Nhóm chấm tác động thang 1–10, công sức theo ngày. Sửa nút lỗi iPhone: tác động 9, 1 ngày → điểm 9. Nén ảnh: 7, 1 ngày → 7. Rút form: 6, 2 ngày → 3. Thêm đánh giá cạnh nút: 5, 1 ngày → 5. Làm lại giao diện: 8, 20 ngày → 0,4. Với 10 ngày, nhóm làm bốn việc đầu (5 ngày) và vài việc nhỏ khác, còn làm lại giao diện để quý sau.',
  takeaway:'Lỗi chặn mua trước, rồi việc tác động lớn tốn ít công; làm lại toàn bộ để sau.',
  apply:'Liệt kê năm việc muốn sửa trên một trang bạn biết. Nói trong 60 giây: chấm tác động và công sức, làm cái nào trước.',
  mistakes:['Bắt đầu từ việc thích làm nhất thay vì việc đáng làm nhất.','Chọn làm lại toàn bộ trang vì "sửa lẻ không bõ".'],
  q:[
  { type:'mcq', stem:'Đoán trước: trong danh sách, việc nào nên làm đầu tiên?',
    options:[{k:'a',t:'Làm lại toàn bộ giao diện vì nó giải quyết mọi thứ một lần'},{k:'b',t:'Đổi font chữ vì đó là việc nhanh nhất, làm xong trong một giờ'},
             {k:'c',t:'Thêm video vì video luôn làm khách thích thú và ở lâu hơn'},{k:'d',t:'Sửa nút đặt hàng lỗi trên iPhone'}],
    answer:'d', why:{a:'Tốn 20 ngày, vượt ngân sách công sức, và còn rủi ro phát sinh lỗi mới.',
      b:'Nhanh nhưng tác động rất thấp.',
      c:'Video tốn công và có thể làm trang chậm.',
      d:'Đúng. Lỗi chặn mua: tác động lớn nhất, công sức nhỏ.'} },
  { type:'mcq', stem:'Sếp muốn dồn cả 10 ngày để làm lại giao diện vì "trang cũ xấu". Bạn đề xuất gì?',
    options:[{k:'a',t:'Làm trước các việc nhanh có tác động lớn, đo kết quả, rồi mới cân nhắc làm lại'},{k:'b',t:'Đồng ý làm lại hết vì giao diện mới sẽ tự sửa mọi vấn đề cũ'},
             {k:'c',t:'Làm lại giao diện nhưng thuê thêm hai lập trình viên để làm nhanh'},{k:'d',t:'Chia đều 1 ngày cho mỗi việc trong mười việc để công bằng'}],
    answer:'a', why:{a:'Đúng. Thu lợi nhanh trong tháng này và có dữ liệu để quyết định việc lớn.',
      b:'Trang mới cũng có thể có lỗi mới; và cả tháng không có cải thiện nào.',
      c:'Thêm người là thêm chi phí; vẫn chưa trả lời vì sao phải làm lại.',
      d:'Chia đều bỏ qua khác biệt tác động; một số việc cần hơn 1 ngày.'} },
  { type:'calc', stem:'Việc "rút form" có tác động 6 điểm, công sức 2 ngày. Việc "làm lại giao diện" tác động 8 điểm, công sức 20 ngày. Điểm ưu tiên (tác động ÷ công sức) của việc rút form gấp bao nhiêu lần việc làm lại giao diện?',
    unit:'lần', ans:7.5, tol:0.05, wrong:[[0.75,'SAI_MAU_SO'],[0.13,'SAI_MAU_SO']], errors:['SAI_MAU_SO'],
    steps:['Rút form: 6 ÷ 2 = 3.','Làm lại giao diện: 8 ÷ 20 = 0,4.','3 ÷ 0,4 = <b>7,5 lần</b>.'] },
  { type:'calc', stem:'Nút đặt hàng lỗi trên iPhone. 40% trong 5.000 lượt vào mỗi tháng dùng iPhone; tỉ lệ mua ở các máy khác là 2%. Nếu iPhone mua ở cùng mức 2% sau khi sửa, và trước đó gần như bằng 0, số đơn thêm mỗi tháng là bao nhiêu?',
    unit:'đơn', ans:40, tol:0.5, wrong:[[100,'SAI_MAU_SO'],[2000,'QUEN_TI_LE_CHUYEN_DOI']], errors:['SAI_MAU_SO'],
    steps:['Lượt vào từ iPhone: 5.000 × 40% = 2.000.','Đơn thêm: 2.000 × 2% = <b>40 đơn</b>.'] },
  { type:'mcq', stem:'Việc "thêm đánh giá cạnh nút" và "đổi font" đều mất 1 ngày. Vì sao đánh giá được ưu tiên?',
    options:[{k:'a',t:'Vì đánh giá luôn làm trang đẹp hơn so với font mới'},{k:'b',t:'Vì cùng công sức nhưng đánh giá tác động nhiều hơn tới quyết định mua'},
             {k:'c',t:'Vì đổi font có thể làm hỏng toàn bộ trang và không thể hoàn tác'},{k:'d',t:'Vì đánh giá miễn phí còn đổi font phải trả tiền bản quyền cao'}],
    answer:'b', why:{a:'Cái đẹp không phải tiêu chí; tác động lên quyết định mới là tiêu chí.',
      b:'Đúng. Công sức bằng nhau thì chọn việc có tác động lớn hơn.',
      c:'Đổi font hoàn tác được; không phải lý do chính.',
      d:'Chi phí bản quyền không phải điểm khác biệt ở đây.'} },
  { type:'mcq', stem:'Chấm điểm tác động bằng cảm tính có nhược điểm gì, và xử lý ra sao?',
    options:[{k:'a',t:'Không có nhược điểm nếu người chấm nhiều kinh nghiệm'},{k:'b',t:'Có thể lệch; nên bỏ chấm điểm và làm theo cảm hứng'},
             {k:'c',t:'Có thể lệch; ghi lý do, dựa số liệu khi có và đo lại sau khi làm'},{k:'d',t:'Có thể lệch; nên để một người ngoài không biết gì về trang tự chấm'}],
    answer:'c', why:{a:'Người nhiều kinh nghiệm vẫn có thể đoán sai.',
      b:'Bỏ chấm điểm thì mất cách so sánh các việc.',
      c:'Đúng. Điểm là ước lượng; ghi lý do và đo lại để chấm tốt hơn lần sau.',
      d:'Người ngoài thiếu dữ kiện, chấm còn lệch hơn.'} },
  { type:'mcq', stem:'Một việc có tác động cao nhưng tốn 15 ngày (ví dụ làm tính năng đặt hàng qua Zalo). Nên xếp thế nào?',
    options:[{k:'a',t:'Bỏ hẳn vì vượt quá 10 ngày công của tháng này'},{k:'b',t:'Làm ngay tháng này, bỏ hết các việc nhỏ khác'},
             {k:'c',t:'Chỉ làm một nửa tính năng trong tháng này rồi dừng hẳn luôn'},{k:'d',t:'Lên kế hoạch cho quý sau, sau khi xong các việc nhanh có tác động lớn'}],
    answer:'d', why:{a:'Tác động cao thì đáng làm; chỉ là không phải bây giờ.',
      b:'Bỏ các việc nhanh là bỏ lợi ích chắc chắn trong tháng này.',
      c:'Tính năng nửa vời không mang lại tác động.',
      d:'Đúng. Việc lớn đáng làm được lên lịch, không chen ngang việc nhanh.'} }
  ] }

]});
